			for (int x = 0; x < n+1; x++){
				if (x < n){
					for (int y = 0; y < m+1; y++){
						if(y < m){
							newTable[x][y] = table[x][y];
							sumAll += newTable[x][y];
						}else{
							for (int a = 0; a < m; a++){
								sumY[x] += table[x][a];
								newTable[x][y] = sumY[x];
							}
						}
					}
				}else{
					for (int z = 0; z < m+1; z++){
						if (z < m){
							for (int b = 0; b < n; b++){
							sumX[z] += table[b][z];
							newTable[x][z] = sumX[z];
							}
						}else{
							newTable[x][z] = sumAll;
						}
					}
				}
			}

