import java.util.NoSuchElementException;

public class Main {

	public static void main(String[] args) {

		FastScanner sc = new FastScanner();
		int N = sc.nextInt();
		int D = sc.nextInt();
		int count = 0;

		count = (int) N / (1 + 2 * D);
		if (N % (1 + 2 * D) != 0)
			count++;

		System.out.println(count);

