import java.io.PrintWriter;

public class Main {
        public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);
        int ans = 0;

        String[] arr = br.readLine().split(" ");
        int N = Integer.parseInt(arr[0]);
        int D = Integer.parseInt(arr[1]);

        String[][] arr2 = new String[N][D];
        for (int i = 0; i < N; i++) {
            arr2[i] = br.readLine().split(" ");       
        }

        for (int i = 0; i < N - 1; i++) {
            String[] y = arr2[i];
            for (int j = i + 1; j < N; j++) {
                String[] z = arr2[j];
                ans += check(D, y, z);
            }
        }

        out.println(ans);
        out.close();
    }

    private static int check(int D, String[] arr1, String[] arr2) {
        int sum = 0;
        for (int i = 0; i < D; i++) {
            int y = Integer.parseInt(arr1[i]);
            int z = Integer.parseInt(arr2[i]);
            sum += Math.pow(y - z, 2);
        }
        double sqrt = Math.sqrt(sum);
        return sqrt % 1 == 0 ? 1 : 0;
    }
}

import java.util.*;

public class Main {

	public static boolean dis(int x[], int y[], int d){
		long ans = 0;
		for(int i = 0; i < d; ++i){
			int tmpx = x[i];
			int tmpy = y[i];
			ans += (tmpx - tmpy) * (tmpx - tmpy);
		}
		double ansd = Math.sqrt((double)ans);
		return (ansd == Math.floor(ansd));
	}

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt(), d = sc.nextInt();
		int x[][] = new int[n][d];
