			for (int j = 0; j < d; ++j)
				x[i][j] = sc.nextInt();
		sc.close();
		int ans = 0;
		for(int i = 0; i < n;++i){
			for(int j = i + 1; j < n; ++j){
				if(dis(x[i], x[j], d))++ans;
			}
		}

