/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        TaskC solver = new TaskC();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskC {
        static long[] memo = new long[100000 + 1];

        public void solve(int testNumber, InputReader in, OutputWriter out) {
            Arrays.fill(memo, -1);
            int N = in.readInt();
            int M = in.readInt();
            for (int i = 0; i < M; i++) {
                memo[in.readInt()] = 0;
            }
            long result = func(N);
            out.printLine(result % 1000000007);

        }

        public long func(int n) {
            if (memo[n] != -1) {
                return memo[n];
            }
            if (n == 0) {
                return 0;
            }
            if (n == 1) {
                return 1;
            }
            if (n == 2) {
                if (memo[1] == 0) {
                    return 1;
                }
                return 2;
            }

            memo[n] = (func(n - 1) + func(n - 2)) % 1000000007;
            return memo[n];
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void close() {
            writer.close();
        }

        public void printLine(long i) {
            writer.println(i);
        }

    }
}

import java.util.Scanner;

public class Main {
  private static final int mod = 1_000_000_007;
  private static void solve(int n, int m, int[] a) {
    int brokenIndex = 0;
    int[] steps = new int[n + 1];
    steps[0] = 1;
    if (brokenIndex < m && a[brokenIndex] == 1) {
      brokenIndex++;
    } else {
      steps[1] = 1;
    }
    for (int i = 2; i <= n; i++) {
      if (brokenIndex < m && a[brokenIndex] == i) {
        steps[i] = 0;
        brokenIndex++;
      } else {
        steps[i] = steps[i - 1] + steps[i - 2];
        if (steps[i] >= mod) steps[i] -= mod;
      }
    }
    System.out.println(steps[n]);
  }
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    String[] nums = sc.nextLine().split(" ");
    int n = Integer.parseInt(nums[0]);
    int m = Integer.parseInt(nums[1]);
    int[] a = new int[m];
    for (int i = 0; i < m; i++) a[i] = Integer.parseInt(sc.nextLine());
    sc.close();
    solve(n, m, a);
  }
}

