        int[] H = new int[n];
        for (int i = 0; i < n; i++) H[i] = sc.nextInt();
        System.out.println(helper(H));
        sc.close();
    }

    public static int helper(int[] A) {
        int res = 0, max = A[0];
        for (int a : A) {
            if (a >= max) {
                max = a;
                res++;
            }
        }
        return res;
